using System;
using System.Linq;
using UnityEngine;
using UnityEditor;
public static class ValidateEquipmentClimb {
static void Capture(VehiclePhysics v,string path){var c=Camera.main;var pos=c.transform.position;var rot=c.transform.rotation;var target=c.targetTexture;var active=RenderTexture.active;var rt=RenderTexture.GetTemporary(1280,800,24);try{var rear=v.axles[v.axles.Length-1].leftVisual.position;c.transform.position=rear-v.transform.right*4-v.transform.forward*2+Vector3.up*1.3f;c.transform.LookAt(rear+Vector3.up*.35f);c.targetTexture=rt;c.Render();RenderTexture.active=rt;var t=new Texture2D(1280,800,TextureFormat.RGB24,false);t.ReadPixels(new Rect(0,0,1280,800),0,0);t.Apply();System.IO.File.WriteAllBytes(path,t.EncodeToPNG());UnityEngine.Object.DestroyImmediate(t);}finally{c.transform.SetPositionAndRotation(pos,rot);c.targetTexture=target;RenderTexture.active=active;RenderTexture.ReleaseTemporary(rt);}}
public static string Main(){if(!Application.isPlaying)throw new Exception("Requires Play");var v=UnityEngine.Object.FindAnyObjectByType<VehiclePhysics>();var rb=v.GetComponent<Rigidbody>();var route=UnityEngine.Object.FindAnyObjectByType<AuthoredForestRoute>();var pos=rb.position;var rot=rb.rotation;var input=v.Input;bool automatic=v.automaticSimulation,external=v.externalControl,pause=EditorApplication.isPaused;var mode=Physics.simulationMode;var chains=v.GetComponent<TruckChains>();bool installed=chains.Installed;bool originalDrive=v.FourWheelDrive;var beforeVelocity=rb.linearVelocity;var beforeAngular=rb.angularVelocity;string report="";
try {EditorApplication.isPaused=true;Physics.simulationMode=SimulationMode.Script;v.automaticSimulation=false;v.externalControl=true;rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;v.SetInput(new VehicleControlInput{handbrake=true});if(chains.Installed){if(!chains.RequestToggle())throw new Exception("Remove chains failed");chains.Advance(chains.installationSeconds+.1f);}
route.Prepare();int arm=1,block=4;float distance=18;Vector3 p=route.RoutePoint(arm,block,distance);Vector3 forward=(route.RoutePoint(arm,block,distance+4)-p).normalized;
var groundHits=Physics.RaycastAll(p+Vector3.up*5,Vector3.down,10).Where(h=>h.collider is MeshCollider&&h.normal.y>.6f).OrderBy(h=>Mathf.Abs(h.point.y-p.y)).ToArray();if(groundHits.Length==0)throw new Exception("Actual road absent at "+p);var ground=groundHits[0];p=ground.point+ground.normal*.65f;rb.position=p;rb.rotation=Quaternion.LookRotation(Vector3.ProjectOnPlane(forward,ground.normal),ground.normal);v.transform.SetPositionAndRotation(rb.position,rb.rotation);v.ResetState();v.SetTransmission(false,false);v.SetFourWheelDrive(true);Physics.SyncTransforms();var sprays=v.GetComponentsInChildren<ParticleSystem>().Where(x=>x.name.StartsWith("Wheel soil spray")).ToArray();Action step=()=>{v.Simulate(.01f);Physics.Simulate(.01f);v.SendMessage("LateUpdate");foreach(var ps in sprays)ps.Simulate(.01f,false,false,true);};v.SetInput(new VehicleControlInput{brake=1});for(int i=0;i<200;i++)step();
Vector3 start=rb.position;var rear=v.axles[v.axles.Length-1];float[] maxRpm={0,0},maxSpin={0,0},visualDegrees={0,0};var wheels=new[]{rear.left,rear.right};var visuals=new[]{rear.leftVisual,rear.rightVisual};int particles=v.GetComponent<VehicleWheelEffects>().EmittedParticles;v.SetInput(new VehicleControlInput{throttle=1});for(int i=0;i<600;i++){var previous=visuals.Select(t=>Quaternion.Inverse(rb.rotation)*t.rotation).ToArray();step();if(i==400||i==405)Capture(v,"work/RearWheelspin"+i+".png");for(int j=0;j<2;j++){maxRpm[j]=Mathf.Max(maxRpm[j],Mathf.Abs(wheels[j].rpm));visualDegrees[j]+=Quaternion.Angle(previous[j],Quaternion.Inverse(rb.rotation)*visuals[j].rotation);if(wheels[j].GetGroundHit(out var h))maxSpin[j]=Mathf.Max(maxSpin[j],Mathf.Abs(wheels[j].rpm*Mathf.PI/30*wheels[j].radius-Vector3.Dot(rb.GetPointVelocity(h.point),h.forwardDir)));}}
float travel=Vector3.Dot(rb.position-start,forward);int emitted=v.GetComponent<VehicleWheelEffects>().EmittedParticles-particles;report="Actual authored forest arm1/block4/d18, grade8.41deg, 4WD HIGH full throttle 6s, chains OFF; contact="+ground.collider.name+"; travel="+travel.ToString("F2")+"m; rear RPM="+string.Join("/",maxRpm.Select(x=>x.ToString("F0")))+"; rear slip m/s="+string.Join("/",maxSpin.Select(x=>x.ToString("F1")))+"; rear visual deg="+string.Join("/",visualDegrees.Select(x=>x.ToString("F0")))+"; particles="+emitted;
if(maxSpin.Any(x=>x<2)||visualDegrees.Any(x=>x<360)||emitted<100||travel<1||travel>50)throw new Exception(report);return "PASS "+report;
}finally{rb.linearVelocity=Vector3.zero;rb.angularVelocity=Vector3.zero;v.SetInput(new VehicleControlInput{handbrake=true});if(chains.Installed!=installed){chains.RequestToggle();chains.Advance(chains.installationSeconds+.1f);}rb.position=pos;rb.rotation=rot;v.transform.SetPositionAndRotation(pos,rot);rb.linearVelocity=beforeVelocity;rb.angularVelocity=beforeAngular;v.ResetState();v.SetFourWheelDrive(originalDrive);v.SetInput(input);v.automaticSimulation=automatic;v.externalControl=external;Physics.simulationMode=mode;EditorApplication.isPaused=pause;}}
}

